create schema retail;
create table retail.branch(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references platform.tenant(id),code varchar(60) not null,name varchar(160) not null,active boolean not null default true,unique(tenant_id,code),unique(tenant_id,id));
create table retail.warehouse(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,branch_id uuid not null,code varchar(60) not null,name varchar(160) not null,active boolean not null default true,unique(tenant_id,code),unique(tenant_id,id),foreign key(tenant_id,branch_id) references retail.branch(tenant_id,id));
create table retail.access_scope(tenant_id uuid not null,account_id uuid not null references identity.account(id),branch_id uuid not null,warehouse_id uuid not null,primary key(tenant_id,account_id,warehouse_id),foreign key(tenant_id,warehouse_id) references retail.warehouse(tenant_id,id),foreign key(tenant_id,branch_id) references retail.branch(tenant_id,id));
create table retail.sku(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references platform.tenant(id),code varchar(60) not null,name varchar(160) not null,barcode varchar(100),variant varchar(160) not null default '',unit varchar(40) not null,units jsonb not null default '{}',tracking varchar(10) not null default 'NONE' check(tracking in ('NONE','LOT','SERIAL')),price numeric(20,4) not null default 0 check(price>=0),vat numeric(8,4) not null default 0 check(vat>=0 and vat<=100),return_days int not null default 0 check(return_days>=0),warranty_days int not null default 0 check(warranty_days>=0),allow_opened boolean not null default false,weight numeric(20,4) not null default 0 check(weight>=0),active boolean not null default true,version int not null default 0,unique(tenant_id,code),unique(tenant_id,barcode),unique(tenant_id,id));
create table retail.partner(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references platform.tenant(id),code varchar(60) not null,name varchar(160) not null,kind varchar(15) not null check(kind in ('CUSTOMER','SUPPLIER','COLLABORATOR')),phone varchar(60) not null default '',email varchar(160) not null default '',address text not null default '',customer_group varchar(80) not null default '',active boolean not null default true,unique(tenant_id,code),unique(tenant_id,id));
create table retail.price_rule(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,sku_id uuid not null,partner_id uuid,customer_group varchar(80) not null default '',branch_id uuid,channel varchar(30) not null default '',min_qty numeric(20,4) not null default 1 check(min_qty>0),price numeric(20,4) not null check(price>=0),priority int not null default 0,valid_from date not null,valid_to date not null,foreign key(tenant_id,sku_id) references retail.sku(tenant_id,id),foreign key(tenant_id,partner_id) references retail.partner(tenant_id,id),foreign key(tenant_id,branch_id) references retail.branch(tenant_id,id),check(valid_to>=valid_from));
create table retail.promotion(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,sku_id uuid not null,name varchar(160) not null,percent numeric(8,4) not null check(percent>0 and percent<=100),priority int not null default 0,stackable boolean not null default false,valid_from date not null,valid_to date not null,foreign key(tenant_id,sku_id) references retail.sku(tenant_id,id),check(valid_to>=valid_from));
create table retail.setting(tenant_id uuid primary key references platform.tenant(id),discount_limit numeric(8,4) not null default 0 check(discount_limit>=0 and discount_limit<=100));
create table retail.document(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,number varchar(80) not null,type varchar(30) not null,status varchar(30) not null default 'DRAFT',branch_id uuid not null,warehouse_id uuid not null,destination_id uuid,partner_id uuid,source_id uuid,channel varchar(30) not null default 'COUNTER',note text not null default '',reason text not null default '',creator_id uuid not null references identity.account(id),approver_id uuid references identity.account(id),version int not null default 0,total numeric(20,0) not null default 0,paid numeric(20,0) not null default 0 check(paid>=0),fee numeric(20,0) not null default 0 check(fee>=0),cost_pending boolean not null default false,method varchar(40) not null default 'CASH',metadata jsonb not null default '{}',created_at timestamptz not null default now(),posted_at timestamptz,unique(tenant_id,number),unique(tenant_id,id),foreign key(tenant_id,branch_id) references retail.branch(tenant_id,id),foreign key(tenant_id,warehouse_id) references retail.warehouse(tenant_id,id),foreign key(tenant_id,destination_id) references retail.warehouse(tenant_id,id),foreign key(tenant_id,partner_id) references retail.partner(tenant_id,id),foreign key(tenant_id,source_id) references retail.document(tenant_id,id));
create table retail.line(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,document_id uuid not null,sku_id uuid not null,source_line_id uuid,position int not null,sku_snapshot jsonb not null,unit varchar(40) not null,ratio numeric(20,4) not null check(ratio>0),qty numeric(20,4) not null check(qty>0),base_qty numeric(20,4) not null check(base_qty>0),price numeric(20,4) not null check(price>=0),discount numeric(20,0) not null default 0,vat numeric(8,4) not null default 0,net numeric(20,0) not null,tax numeric(20,0) not null,total numeric(20,0) not null,cost numeric(24,8) not null default 0,progress numeric(20,4) not null default 0,closed_qty numeric(20,4) not null default 0,lot varchar(100) not null default '',expiry date,serials jsonb not null default '[]',segments jsonb not null default '[]',count_snapshot numeric(20,4),condition varchar(20) not null default 'GOOD',rule_snapshot jsonb not null default '{}',unique(tenant_id,id),foreign key(tenant_id,document_id) references retail.document(tenant_id,id),foreign key(tenant_id,sku_id) references retail.sku(tenant_id,id),foreign key(tenant_id,source_line_id) references retail.line(tenant_id,id));
create table retail.balance(tenant_id uuid not null,warehouse_id uuid not null,sku_id uuid not null,qty numeric(20,4) not null default 0 check(qty>=0),quarantine numeric(20,4) not null default 0 check(quarantine>=0 and quarantine<=qty),value numeric(24,8) not null default 0 check(value>=0),primary key(tenant_id,warehouse_id,sku_id),foreign key(tenant_id,warehouse_id) references retail.warehouse(tenant_id,id),foreign key(tenant_id,sku_id) references retail.sku(tenant_id,id));
create table retail.lot(tenant_id uuid not null,warehouse_id uuid not null,sku_id uuid not null,code varchar(100) not null,expiry date not null,qty numeric(20,4) not null default 0 check(qty>=0),quarantine numeric(20,4) not null default 0 check(quarantine>=0 and quarantine<=qty),primary key(tenant_id,warehouse_id,sku_id,code),foreign key(tenant_id,warehouse_id,sku_id) references retail.balance(tenant_id,warehouse_id,sku_id));
create table retail.serial(tenant_id uuid not null,serial varchar(100) not null,sku_id uuid not null,warehouse_id uuid,location varchar(20) not null check(location in ('AVAILABLE','QUARANTINE','SOLD','TRANSIT','SUPPLIER')),source_line_id uuid,primary key(tenant_id,serial),foreign key(tenant_id,sku_id) references retail.sku(tenant_id,id),foreign key(tenant_id,warehouse_id) references retail.warehouse(tenant_id,id));
create table retail.movement(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,warehouse_id uuid not null,sku_id uuid not null,document_id uuid not null,line_id uuid not null,kind varchar(30) not null,qty numeric(20,4) not null,value numeric(24,8) not null,quarantine numeric(20,4) not null default 0,details jsonb not null default '{}',created_at timestamptz not null default now(),foreign key(tenant_id,warehouse_id) references retail.warehouse(tenant_id,id),foreign key(tenant_id,sku_id) references retail.sku(tenant_id,id),foreign key(tenant_id,document_id) references retail.document(tenant_id,id),foreign key(tenant_id,line_id) references retail.line(tenant_id,id));
create table retail.open_item(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,branch_id uuid not null,partner_id uuid,document_id uuid not null,kind varchar(3) not null check(kind in ('AR','AP')),amount numeric(20,0) not null check(amount>=0),credit numeric(20,0) not null default 0 check(credit>=0),allocated numeric(20,0) not null default 0 check(allocated>=0),due_date date,unique(tenant_id,document_id,kind),unique(tenant_id,id),foreign key(tenant_id,document_id) references retail.document(tenant_id,id),foreign key(tenant_id,partner_id) references retail.partner(tenant_id,id),check(allocated+credit<=amount));
create table retail.payment(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,branch_id uuid not null,partner_id uuid,document_id uuid,kind varchar(20) not null check(kind in ('RECEIPT','PAYMENT','REFUND','SUPPLIER_REFUND','COMMISSION')),amount numeric(20,0) not null check(amount>0),allocated numeric(20,0) not null default 0 check(allocated>=0 and allocated<=amount),method varchar(40) not null,reference text not null default '',created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,document_id) references retail.document(tenant_id,id),foreign key(tenant_id,partner_id) references retail.partner(tenant_id,id));
create table retail.allocation(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,payment_id uuid not null,open_item_id uuid not null,amount numeric(20,0) not null check(amount>0),foreign key(tenant_id,payment_id) references retail.payment(tenant_id,id),foreign key(tenant_id,open_item_id) references retail.open_item(tenant_id,id));
create table retail.delivery(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,branch_id uuid not null,issue_id uuid not null,status varchar(20) not null default 'PREPARING',carrier varchar(160) not null default '',tracking varchar(160) not null default '',cod numeric(20,0) not null default 0 check(cod>=0),fee numeric(20,0) not null default 0 check(fee>=0),settled numeric(20,0) not null default 0 check(settled>=0),note text not null default '',version int not null default 0,unique(tenant_id,issue_id),foreign key(tenant_id,issue_id) references retail.document(tenant_id,id),check(settled<=cod));
create table retail.care(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,branch_id uuid not null,partner_id uuid not null,note text not null,due_at timestamptz,done boolean not null default false,creator_id uuid not null,created_at timestamptz not null default now(),foreign key(tenant_id,partner_id) references retail.partner(tenant_id,id));
create table retail.warranty(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,branch_id uuid not null,source_line_id uuid not null,serial varchar(100) not null default '',qty numeric(20,4) not null default 1,status varchar(20) not null default 'RECEIVED',note text not null,warehouse_id uuid not null,version int not null default 0,created_at timestamptz not null default now(),foreign key(tenant_id,source_line_id) references retail.line(tenant_id,id),foreign key(tenant_id,warehouse_id) references retail.warehouse(tenant_id,id));
create table retail.command(tenant_id uuid not null,account_id uuid not null,key varchar(120) not null,operation varchar(200) not null,hash varchar(64) not null,result jsonb not null,created_at timestamptz not null default now(),primary key(tenant_id,account_id,key));
create table retail.import_batch(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,branch_id uuid not null,warehouse_id uuid not null,kind varchar(30) not null,checksum varchar(64) not null,rows jsonb not null,errors jsonb not null,status varchar(20) not null default 'PREVIEW',creator_id uuid not null,created_at timestamptz not null default now(),unique(tenant_id,kind,checksum));
create index on retail.document(tenant_id,branch_id,created_at desc);
create index on retail.line(tenant_id,document_id);
create index on retail.movement(tenant_id,warehouse_id,sku_id,created_at);
create index on retail.open_item(tenant_id,branch_id,partner_id);
alter table retail.line add column counted_qty numeric(20,4) check(counted_qty>=0);
alter table retail.line add column count_lots jsonb not null default '[]';
alter table retail.serial drop constraint serial_location_check;
alter table retail.serial add constraint serial_location_check check(location in ('AVAILABLE','QUARANTINE','SOLD','TRANSIT','SUPPLIER','MISSING'));

-- Tenant isolation is enforced by PostgreSQL in addition to application branch/warehouse scope.
do $$ declare tab text; begin
  for tab in select tablename from pg_tables where schemaname='retail' loop
    execute format('alter table retail.%I enable row level security',tab);
    execute format('alter table retail.%I force row level security',tab);
    execute format('create policy tenant_scope on retail.%I using (tenant_id = nullif(current_setting(''core.tenant_id'',true),'''')::uuid) with check (tenant_id = nullif(current_setting(''core.tenant_id'',true),'''')::uuid)',tab);
  end loop;
  if exists(select 1 from pg_roles where rolname='core_app') then
    grant usage on schema retail to core_app;
    grant select,insert,update on all tables in schema retail to core_app;
    revoke update on retail.movement,retail.allocation from core_app;
  end if;
end $$;

-- No business stock/debt is seeded. Existing platform administrator can configure the first shop.
insert into retail.setting(tenant_id) select id from platform.tenant;
